@foreach($blogs as $blog)<div class="{{ $home ? 'col-xl-4 col-md-6' : 'col-md-6' }} d-flex"><article class="public-blog-card"><a class="public-blog-image" href="{{ route('blogs.show',$blog) }}">@if($blog->image)<img src="{{ asset('storage/'.$blog->image) }}" alt="{{ $blog->title }}" loading="lazy">@else<div class="public-blog-placeholder"><i class="fas fa-newspaper"></i></div>@endif</a><div class="public-blog-body"><div class="public-blog-date"><i class="fas fa-calendar-alt"></i> {{ ($blog->published_at?:$blog->created_at)->format('M d-Y') }}</div><span class="public-blog-category">{{ $blog->category->name }}</span><h3><a href="{{ route('blogs.show',$blog) }}">{{ $blog->title }}</a></h3><p>{{ str(strip_tags($blog->description))->squish()->limit($home?115:150) }}</p><a class="public-blog-read" href="{{ route('blogs.show',$blog) }}">Read More</a></div></article></div>@endforeach
